@pytest.fixture
def mock_database_connection():
    """模拟数据库连接"""
    conn = MagicMock()
    conn.cursor.return_value = MagicMock()
    conn.cursor.return_value.execute.return_value = None
    conn.cursor.return_value.fetchall.return_value = []
    conn.cursor.return_value.fetchone.return_value = None
    return conn


@pytest.fixture
def mock_cache():
    """模拟缓存对象"""
    cache_store = {}

    mock = MagicMock()
    mock.get.side_effect = lambda key: cache_store.get(key)
    mock.set.side_effect = lambda key, value: cache_store.update({key: value})
    mock.delete.side_effect = lambda key: cache_store.pop(key, None)
    mock.exists.side_effect = lambda key: key in cache_store
    mock.clear.side_effect = lambda: cache_store.clear()

    return mock


