    return test_file


@pytest.fixture
def api_client_mock():
    """模拟API客户端"""
    client = MagicMock()

    def mock_get(endpoint, **kwargs):
        response = Mock()
        response.status_code = 200
        response.json.return_value = {"endpoint": endpoint, "status": "success"}
        return response

    def mock_post(endpoint, data=None, **kwargs):
        response = Mock()
        response.status_code = 201
        response.json.return_value = {"endpoint": endpoint, "created": True}
        return response

    client.get = Mock(side_effect=mock_get)
    client.post = Mock(side_effect=mock_post)
    client.put = Mock(return_value=Mock(status_code=200, json=lambda: {"updated": True}))
    client.delete = Mock(return_value=Mock(status_code=204))

    return client


